import{_ as t,o as r,c as a,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const g=JSON.parse('{"title":"Sources and terminology","description":"","frontmatter":{},"headers":[],"relativePath":"sources.md","filePath":"sources.md","lastUpdated":1794376220000}'),i={name:"sources.md"};function o(l,e,s,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="sources-and-terminology" tabindex="-1">Sources and terminology <a class="header-anchor" href="#sources-and-terminology" aria-label="Permalink to &quot;Sources and terminology&quot;">​</a></h1><p>Primary documentation supports technical capabilities and attribution. Technology selection and review findings are our analysis. Links on each architecture page attach evidence to the relevant claim.</p><h2 id="product-interface-and-serving" tabindex="-1">Product interface and serving <a class="header-anchor" href="#product-interface-and-serving" aria-label="Permalink to &quot;Product interface and serving&quot;">​</a></h2><ul><li><a href="https://svelte.dev/docs/svelte/$state" target="_blank" rel="noreferrer">Svelte reactivity</a>: granular state updates.</li><li><a href="https://svelte.dev/docs/kit/page-options" target="_blank" rel="noreferrer">SvelteKit page options</a>: route rendering choices.</li><li><a href="https://svelte.dev/docs/kit/state-management" target="_blank" rel="noreferrer">SvelteKit state management</a>: server/client state boundaries.</li><li><a href="https://tokio.rs/tokio/tutorial/select" target="_blank" rel="noreferrer">Tokio cancellation</a>: local future cancellation and background work.</li><li><a href="https://docs.rs/tokio/latest/tokio/task/fn.spawn_blocking.html" target="_blank" rel="noreferrer">Tokio blocking tasks</a>: blocking-work execution and limitations.</li><li><a href="https://docs.nats.io/concepts/jetstream" target="_blank" rel="noreferrer">NATS JetStream</a>: retained events and consumer acknowledgments.</li></ul><h2 id="retrieval-and-enrichment" tabindex="-1">Retrieval and enrichment <a class="header-anchor" href="#retrieval-and-enrichment" aria-label="Permalink to &quot;Retrieval and enrichment&quot;">​</a></h2><ul><li><a href="https://sqlite.org/fts5.html" target="_blank" rel="noreferrer">SQLite FTS5</a>: keyword search and BM25.</li><li><a href="https://www.sqlite.org/vec1.html" target="_blank" rel="noreferrer">SQLite Vec1</a> and <a href="https://www.sqlite.org/vec1doc.html" target="_blank" rel="noreferrer">manual</a>: vector modes and filtered queries.</li><li><a href="https://github.com/asg017/sqlite-vec/releases" target="_blank" rel="noreferrer">sqlite-vec releases</a>: version-specific vector capabilities.</li><li><a href="https://sqlite.org/wal.html" target="_blank" rel="noreferrer">SQLite WAL</a>: concurrency and checkpointing.</li><li><a href="https://sqlite.org/lang_with.html" target="_blank" rel="noreferrer">SQLite recursive queries</a>: hierarchical and graph traversal.</li><li><a href="https://docling-project.github.io/docling/concepts/chunking/" target="_blank" rel="noreferrer">Docling chunking</a>: structural and token-aware chunks.</li><li><a href="https://spacy.io/api/entitylinker" target="_blank" rel="noreferrer">spaCy entity linking</a>: linking mentions to canonical identifiers.</li><li><a href="https://microsoft.github.io/graphrag/index/default_dataflow/" target="_blank" rel="noreferrer">Microsoft GraphRAG dataflow</a>: extraction and enrichment pipeline reference.</li><li><a href="https://dagster.io/docs/guides/build/assets/modeling-etl-pipelines" target="_blank" rel="noreferrer">Dagster ETL modeling</a> and <a href="https://docs.temporal.io/workflow-execution" target="_blank" rel="noreferrer">Temporal workflows</a>: orchestration candidates.</li></ul><h2 id="review-foundations" tabindex="-1">Review foundations <a class="header-anchor" href="#review-foundations" aria-label="Permalink to &quot;Review foundations&quot;">​</a></h2><ul><li><a href="https://blog.cleancoder.com/uncle-bob/2012/08/13/the-clean-architecture.html" target="_blank" rel="noreferrer">Robert C. Martin: The Clean Architecture</a>.</li><li><a href="https://www.informit.com/store/design-patterns-elements-of-reusable-object-oriented-software-9780201633610" target="_blank" rel="noreferrer">Gang of Four: Design Patterns</a>.</li><li><a href="https://www.informit.com/articles/article.aspx?p=1404056" target="_blank" rel="noreferrer">Gang of Four retrospective</a>.</li><li><a href="https://rust-lang.org/governance/people/graydon/" target="_blank" rel="noreferrer">Rust&#39;s attribution of Graydon Hoare</a>.</li><li><a href="https://venge.net/graydon/talks/intro-talk-2.pdf" target="_blank" rel="noreferrer">Hoare&#39;s early Rust presentation</a> and <a href="https://github.com/graydon/rust-prehistory" target="_blank" rel="noreferrer">author-published archive</a>.</li></ul><h2 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning in this design</th></tr></thead><tbody><tr><td>DAG</td><td>A directed acyclic dependency graph of processing artifacts</td></tr><tr><td>NER</td><td>Detection of named entity mentions in text</td></tr><tr><td>Entity resolution</td><td>Choosing which canonical identity a mention refers to, or preserving uncertainty</td></tr><tr><td>Claim</td><td>An attributed assertion with evidence and qualifiers</td></tr><tr><td>Augmentation</td><td>Generated, source-linked context kept separate from original evidence</td></tr><tr><td>BM25</td><td>A lexical ranking function provided here by FTS5</td></tr><tr><td>ANN</td><td>Approximate nearest-neighbor retrieval, evaluated against an exact reference</td></tr><tr><td>SSE</td><td>HTTP event framing for incremental server-to-browser delivery</td></tr><tr><td>Fencing</td><td>Rejecting writes from an obsolete run/worker authority</td></tr><tr><td>Outbox</td><td>A committed record used to reliably publish a corresponding boundary event</td></tr><tr><td>RRF</td><td>Reciprocal rank fusion, combining result ranks from different retrieval signals</td></tr></tbody></table>',10)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
